Q: Defaulting a &lt;select&gt; to the first fetched option via useEffect keeps resetting the user&#39;s later selection — what&#39;s the correct pattern? A: <p>Figured this out, posting it as an answer myself instead of editing the question.</p>
<p>Turns out the fix is to just stop syncing selectedId with an effect at all and compute it during render instead:</p>
<p>jsx</p>
<pre><code>function Picker({ loadOptions }) {
  const [options, setOptions] = useState(null);
  const [picked, setPicked] = useState(&quot;&quot;); // only ever set by the user

  useEffect(() =&gt; {
    loadOptions().then(setOptions);
  }, [loadOptions]);

  // Derived, not stored: falls back to the first option only when
  // the user hasn't picked one yet. No second effect, no reset.
  const selectedId = picked || (options?.length ? options[0].id : &quot;&quot;);

  return (
    &lt;select value={selectedId} onChange={(e) =&gt; setPicked(e.target.value)}&gt;
      {(options || []).map((o) =&gt; (
        &lt;option key={o.id} value={o.id}&gt;{o.name}&lt;/option&gt;
      ))}
    &lt;/select&gt;
  );
}
</code></pre>
<p>picked only ever changes inside onChange, it doesn't depend on options at all, so a refetch can't touch it anymore. And since selectedId is just computed inline instead of set through an effect, there's no extra render and nothing flashes empty first.</p>
<p>Only real gotcha: if options ever comes back with a totally different list and picked was pointing at an id that's not in it anymore, you get a select with a value that doesn't match any option, most browsers just show that as blank. Wasn't an issue here since my list doesn't change mid-session, but if yours does, something like this handles it:</p>
<p>jsx</p>
<pre><code>const selectedId = options?.some(o =&gt; o.id === picked)
  ? picked
  : (options?.[0]?.id ?? &quot;&quot;);
</code></pre>
<p>just so it falls back properly instead of showing a broken looking dropdown.</p>
<h3>Full implementation, file by file(for my own ref. in future_)</h3>
<p>Question only needed the small Picker example above. Here's the actual app that pattern is used in though (shows up in StatsPanel.jsx), since I said I'd post the whole frontend too.</p>
<p>Same naming note as the backend post: App.jsx imports this as ./components/BonusPanels and the component's declared as BonusPanels in the file, so that's the name I'm using below even though it was saved locally as bonusPanel.jsx at one point — that kind of mismatch breaks on case sensitive filesystems.</p>
<p>index.css and App.css are imported but I don't have those to include.</p>
<h5><code>src/main.jsx</code></h5>
<p>jsx</p>
<pre><code>import { StrictMode } from &quot;react&quot;;
import { createRoot } from &quot;react-dom/client&quot;;
import &quot;./index.css&quot;;
import App from &quot;./App.jsx&quot;;

createRoot(document.getElementById(&quot;root&quot;)).render(
  &lt;StrictMode&gt;
    &lt;App /&gt;
  &lt;/StrictMode&gt;
);
</code></pre>
<h5><code>src/App.jsx</code></h5>
<p>jsx</p>
<pre><code>import { useState } from &quot;react&quot;;
import {
  getProducts,
  getCategories,
  getProductStats,
  getCategoryStats,
} from &quot;./api&quot;;
import DateRangeFilter from &quot;./components/DateRangeFilter&quot;;
import SummaryCards from &quot;./components/SummaryCards&quot;;
import StatsPanel from &quot;./components/StatsPanel&quot;;
import BonusPanels from &quot;./components/BonusPanels&quot;;
import &quot;./App.css&quot;;

function App() {
  // The one piece of shared state. Every panel takes it and refetches on change.
  const [range, setRange] = useState({ start_date: &quot;&quot;, end_date: &quot;&quot; });

  return (
    &lt;div className=&quot;app&quot;&gt;
      &lt;header&gt;
        &lt;h1&gt;E-Commerce Analytics&lt;/h1&gt;
        &lt;DateRangeFilter range={range} onChange={setRange} /&gt;
      &lt;/header&gt;

      &lt;SummaryCards range={range} /&gt;

      &lt;div className=&quot;grid-2&quot;&gt;
        &lt;StatsPanel
          title=&quot;Product Analytics&quot;
          range={range}
          loadOptions={getProducts}
          loadStats={getProductStats}
        /&gt;
        &lt;StatsPanel
          title=&quot;Category Analytics&quot;
          range={range}
          loadOptions={getCategories}
          loadStats={getCategoryStats}
        /&gt;
      &lt;/div&gt;

      &lt;BonusPanels range={range} /&gt;
    &lt;/div&gt;
  );
}

export default App;
</code></pre>
<h5><code>src/api.js</code></h5>
<p>javascript</p>
<pre><code>import { useEffect, useState } from &quot;react&quot;;

const BASE_URL = &quot;http://localhost:8000&quot;;

// { start_date: &quot;2026-01-01&quot;, end_date: &quot;&quot; } -&gt; &quot;?start_date=2026-01-01&quot;
// Empty strings are dropped so a blank filter means &quot;all time&quot;.
function query(params) {
  const parts = Object.entries(params).filter(([, value]) =&gt; value);
  if (!parts.length) return &quot;&quot;;
  return &quot;?&quot; + parts.map(([k, v]) =&gt; `${k}=${v}`).join(&quot;&amp;&quot;);
}

async function get(path) {
  const res = await fetch(BASE_URL + path);
  if (!res.ok) {
    const body = await res.json().catch(() =&gt; ({}));
    throw new Error(body.detail || &quot;Request failed&quot;);
  }
  return res.json();
}

// One function per endpoint. Nothing else in the app calls fetch.
export const getCategories = () =&gt; get(&quot;/categories&quot;);
export const getProducts = () =&gt; get(&quot;/products&quot;);

export const getSummary = (range) =&gt; get(&quot;/analytics/summary&quot; + query(range));
export const getProductStats = (id, range) =&gt; get(`/analytics/products/${id}` + query(range));
export const getCategoryStats = (id, range) =&gt; get(`/analytics/categories/${id}` + query(range));

export const getTopProducts = (range) =&gt; get(&quot;/analytics/top-products&quot; + query(range));
export const getTopCategories = (range) =&gt; get(&quot;/analytics/top-categories&quot; + query(range));
export const getTrends = (range) =&gt; get(&quot;/analytics/trends&quot; + query(range));

/**
 * One hook for every fetch, so no component repeats useState + useEffect + error.
 *
 *   const { data, error } = useApi(() =&gt; getSummary(range), [range]);
 *
 * `deps` works exactly like the useEffect dependency array: list whatever the
 * fetch reads, and it refetches when any of those change.
 */
export function useApi(fetcher, deps) {
  const [data, setData] = useState(null);
  const [error, setError] = useState(&quot;&quot;);

  useEffect(() =&gt; {
    setError(&quot;&quot;);
    fetcher()
      .then(setData)
      .catch((e) =&gt; setError(e.message));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);

  return { data, error };
}
</code></pre>
<h5><code>src/components/DateRangeFilter.jsx</code></h5>
<p>jsx</p>
<pre><code>function DateRangeFilter({ range, onChange }) {
  return (
    &lt;div className=&quot;date-filter&quot;&gt;
      &lt;label&gt;
        From
        &lt;input
          type=&quot;date&quot;
          value={range.start_date}
          onChange={(e) =&gt; onChange({ ...range, start_date: e.target.value })}
        /&gt;
      &lt;/label&gt;
      &lt;label&gt;
        To
        &lt;input
          type=&quot;date&quot;
          value={range.end_date}
          onChange={(e) =&gt; onChange({ ...range, end_date: e.target.value })}
        /&gt;
      &lt;/label&gt;
      &lt;button onClick={() =&gt; onChange({ start_date: &quot;&quot;, end_date: &quot;&quot; })}&gt;
        Clear
      &lt;/button&gt;
    &lt;/div&gt;
  );
}

export default DateRangeFilter;
</code></pre>
<h5><code>src/components/StatsPanel.jsx</code></h5>
<p>jsx</p>
<pre><code>import { useState } from &quot;react&quot;;
import { useApi } from &quot;../api&quot;;

/**
 * A dropdown plus the four numbers for whatever is selected.
 *
 * Used TWICE from App.jsx -- once for products, once for categories -- because
 * both panels are the same shape. Only the two loader functions differ.
 */
function StatsPanel({ title, range, loadOptions, loadStats }) {
  const { data: options } = useApi(loadOptions, []);
  const [picked, setPicked] = useState(&quot;&quot;);

  // Default to the first option until the user picks one. Derived, not stored,
  // so there is no second useEffect keeping two pieces of state in sync.
  const selectedId = picked || (options?.length ? options[0].id : &quot;&quot;);

  const { data: stats, error } = useApi(
    () =&gt; (selectedId ? loadStats(selectedId, range) : Promise.resolve(null)),
    [selectedId, range]
  );

  const rows = stats &amp;&amp; [
    [&quot;Orders&quot;, stats.total_orders],
    [&quot;Units Sold&quot;, stats.units_sold],
    [&quot;Revenue&quot;, `$${stats.total_revenue}`],
    [&quot;Avg Order Value&quot;, `$${stats.average_order_value}`],
  ];

  return (
    &lt;section className=&quot;panel&quot;&gt;
      &lt;h2&gt;{title}&lt;/h2&gt;

      &lt;select value={selectedId} onChange={(e) =&gt; setPicked(e.target.value)}&gt;
        {(options || []).map((option) =&gt; (
          &lt;option key={option.id} value={option.id}&gt;
            {option.name}
          &lt;/option&gt;
        ))}
      &lt;/select&gt;

      {error &amp;&amp; &lt;p className=&quot;error&quot;&gt;{error}&lt;/p&gt;}
      {rows &amp;&amp; (
        &lt;ul className=&quot;stat-list&quot;&gt;
          {rows.map(([label, value]) =&gt; (
            &lt;li key={label}&gt;
              &lt;span&gt;{label}&lt;/span&gt;
              &lt;span&gt;{value}&lt;/span&gt;
            &lt;/li&gt;
          ))}
        &lt;/ul&gt;
      )}
    &lt;/section&gt;
  );
}

export default StatsPanel;
</code></pre>
<h5><code>src/components/SummaryCards.jsx</code></h5>
<p>jsx</p>
<pre><code>import { useApi, getSummary } from &quot;../api&quot;;

function SummaryCards({ range }) {
  const { data, error } = useApi(() =&gt; getSummary(range), [range]);

  if (error) return &lt;p className=&quot;error&quot;&gt;{error}&lt;/p&gt;;
  if (!data) return &lt;p&gt;Loading...&lt;/p&gt;;

  // A list of pairs beats four hand-written divs.
  const cards = [
    [&quot;Total Orders&quot;, data.total_orders],
    [&quot;Total Revenue&quot;, `$${data.total_revenue.toLocaleString()}`],
    [&quot;Avg Order Value&quot;, `$${data.average_order_value}`],
    [&quot;Units Sold&quot;, data.units_sold],
  ];

  return (
    &lt;section className=&quot;cards&quot;&gt;
      {cards.map(([label, value]) =&gt; (
        &lt;div className=&quot;card&quot; key={label}&gt;
          &lt;span className=&quot;card-label&quot;&gt;{label}&lt;/span&gt;
          &lt;span className=&quot;card-value&quot;&gt;{value}&lt;/span&gt;
        &lt;/div&gt;
      ))}
    &lt;/section&gt;
  );
}

export default SummaryCards;
</code></pre>
<h5><code>src/components/BonusPanels.jsx</code></h5>
<p>jsx</p>
<pre><code>import { useApi, getTopProducts, getTopCategories, getTrends } from &quot;../api&quot;;

// Everything in this file is bonus. Behind schedule? Delete the file, then drop
// its import AND its &lt;BonusPanels /&gt; line from App.jsx -- back to the core app.

function RankedTable({ title, rows }) {
  return (
    &lt;&gt;
      &lt;h3&gt;{title}&lt;/h3&gt;
      &lt;table&gt;
        &lt;thead&gt;
          &lt;tr&gt;
            &lt;th&gt;Name&lt;/th&gt;
            &lt;th&gt;Units&lt;/th&gt;
            &lt;th&gt;Revenue&lt;/th&gt;
          &lt;/tr&gt;
        &lt;/thead&gt;
        &lt;tbody&gt;
          {rows.map((row) =&gt; (
            &lt;tr key={row.name}&gt;
              &lt;td&gt;{row.name}&lt;/td&gt;
              &lt;td&gt;{row.units_sold}&lt;/td&gt;
              &lt;td&gt;${row.total_revenue}&lt;/td&gt;
            &lt;/tr&gt;
          ))}
        &lt;/tbody&gt;
      &lt;/table&gt;
    &lt;/&gt;
  );
}

function BonusPanels({ range }) {
  const { data: topProducts } = useApi(() =&gt; getTopProducts(range), [range]);
  const { data: topCategories } = useApi(() =&gt; getTopCategories(range), [range]);
  const { data: trends } = useApi(() =&gt; getTrends(range), [range]);

  const days = trends || [];
  // Guard with 1 so an empty list never divides by zero.
  const maxRevenue = Math.max(1, ...days.map((d) =&gt; d.total_revenue));

  return (
    &lt;div className=&quot;grid-2&quot;&gt;
      &lt;section className=&quot;panel&quot;&gt;
        &lt;h2&gt;Top Performers&lt;/h2&gt;
        &lt;RankedTable title=&quot;Products&quot; rows={topProducts || []} /&gt;
        &lt;RankedTable title=&quot;Categories&quot; rows={topCategories || []} /&gt;
      &lt;/section&gt;

      &lt;section className=&quot;panel&quot;&gt;
        &lt;h2&gt;Sales Trend (daily)&lt;/h2&gt;
        {days.length === 0 &amp;&amp; &lt;p&gt;No data for this range.&lt;/p&gt;}
        &lt;div className=&quot;bar-chart&quot;&gt;
          {days.map((day) =&gt; (
            &lt;div className=&quot;bar-row&quot; key={day.day}&gt;
              &lt;span className=&quot;bar-label&quot;&gt;{day.day}&lt;/span&gt;
              &lt;div className=&quot;bar-track&quot;&gt;
                &lt;div
                  className=&quot;bar-fill&quot;
                  style={{ width: `${(day.total_revenue / maxRevenue) * 100}%` }}
                /&gt;
              &lt;/div&gt;
              &lt;span className=&quot;bar-value&quot;&gt;${day.total_revenue}&lt;/span&gt;
            &lt;/div&gt;
          ))}
        &lt;/div&gt;
      &lt;/section&gt;
    &lt;/div&gt;
  );
}

export default BonusPanels;
</code></pre>

Q: How to delete an item from array only on the second click on the same element in React? A: <p>Your handler only does deletes, and there is no branch that selects, so <code>selectedCountry?.Id === id</code> can never be true unless something else sets it. That's why the first click appears to do nothing.</p>
<p>The other issue is that <code>selectedCountry</code> holds a whole object but is initialized to the string <code>'All'</code>. Mixing a sentinel string with an object type means every check needs a guard. Store just the id and use <code>null</code>:</p>
<pre><code>type Country = { Id: number; Name: string };

const [commanders, setCommanders] = useState&lt;Country[]&gt;(initialData);
const [selectedId, setSelectedId] = useState&lt;number | null&gt;(null);

function handleClick(id: number): void {
  if (selectedId === id) {
    setCommanders(prev =&gt; prev.filter(item =&gt; item.Id !== id));
    setSelectedId(null);
  } else {
    setSelectedId(id);
  }
}
</code></pre>
<p>Two clicks on the same item deletes it. Clicking a different item moves the selection instead, so you don't get an accidental delete after switching.</p>

Q: Springdoc - How do I add externalDocs to OpenAPI swagger UI auto generated documentation A: <p>All I needed to do was add <code>@Configuration</code> and update my pom.xml to have the following.</p>
<pre class="lang-xml prettyprint-override"><code>        &lt;dependency&gt;
            &lt;groupId&gt;org.springdoc&lt;/groupId&gt;
            &lt;artifactId&gt;springdoc-openapi-ui&lt;/artifactId&gt;
            &lt;version&gt;1.4.4&lt;/version&gt;
        &lt;/dependency&gt;
        &lt;dependency&gt;
            &lt;groupId&gt;org.springdoc&lt;/groupId&gt;
            &lt;artifactId&gt;springdoc-openapi-webmvc-core&lt;/artifactId&gt;
            &lt;version&gt;1.4.4&lt;/version&gt;
        &lt;/dependency&gt;

</code></pre>
<pre class="lang-java prettyprint-override"><code>import io.swagger.v3.oas.models.ExternalDocumentation;
import io.swagger.v3.oas.models.OpenAPI;
import io.swagger.v3.oas.models.info.Info;
import io.swagger.v3.oas.models.info.License;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
public class springShopOpenAPI{



    @Bean
    public OpenAPI customOpenAPI(){
        return new OpenAPI()
                .info(new Info().title(&quot;SpringShop API&quot;)
                        .description(&quot;Spring shop sample application&quot;)
                        .version(&quot;v0.0.1&quot;)
                        .license(new License().name(&quot;Apache 2.0&quot;).url(&quot;http://springdoc.org&quot;)))
                .externalDocs(new ExternalDocumentation()
                        .description(&quot;SpringShop Wiki Documentation&quot;)
                        .url(&quot;https://springshop.wiki.github.org/docs&quot;));
    }

}
</code></pre>
